package studyfix;

import java.nio.file.*;
import java.util.*;
import java.net.*;
import java.net.http.*;
import studyfix.assignment.transport.AssignmentTcpServer;
import static studyfix.assignment.protocol.AssignmentJson.*;
import static studyfix.TeacherDashboardIntegrationTest.request;
import static studyfix.TeacherDashboardIntegrationTest.login;

public final class StudentDirectoryIntegrationTest {
 static int checks;
 static void check(boolean yes,String message){if(!yes)throw new AssertionError(message);checks++;}
 static Map<String,Object> call(String base,String token,Map<String,Object> body)throws Exception{var r=request(base,token,"/api/admin",body);check(r.status()==200,"action "+(body==null?"GET":body.get("action"))+": "+r.json());return map(r.json().get("data"));}
 static List<Map<String,Object>> users(String base,String token)throws Exception{return list(call(base,token,null).get("users")).stream().map(v->map(v)).toList();}
 static Map<String,Object> user(String base,String token,String id)throws Exception{return users(base,token).stream().filter(u->id.equals(u.get("userId"))).findFirst().orElseThrow();}
 static Map<String,Object> student(String code,String name,String username,String room){return mapOf("studentCode",code,"displayName",name,"username",username,"password","Student12345!","email",username+"@studyfix.local","accountStatus","ACTIVE","classId",room);}
 static String create(String base,String token,Map<String,Object> row)throws Exception{var body=new LinkedHashMap<>(row);body.put("action","STUDENT_CREATE");return String.valueOf(list(call(base,token,body).get("userIds")).getFirst());}
 static HttpResponse<String> preview(String base,String token,byte[] bytes)throws Exception{return HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create(base+"/api/admin/students/import-preview")).header("Authorization","Bearer "+token).POST(HttpRequest.BodyPublishers.ofByteArray(bytes)).build(),HttpResponse.BodyHandlers.ofString());}
 public static void main(String[] args)throws Exception{
  System.clearProperty("studyfix.legacy.sqlite");System.setProperty("studyfix.management.db","sqlite");System.setProperty("studyfix.screen.port","0");System.setProperty("studyfix.web.port","0");System.setProperty("studyfix.web.ws.port","0");System.setProperty("studyfix.web.root",Path.of("../web-client/static").toAbsolutePath().toString());Files.createDirectories(Path.of("build-student-directory"));
  Path temp=Files.createTempDirectory(Path.of("build-student-directory"),"integration-"),management=temp.resolve("management.db");System.setProperty("studyfix.management.sqlite",management.toAbsolutePath().toString());var db=new ManagementDatabase(new ManagementConfig("jdbc:sqlite:"+management.toAbsolutePath()));String teacher=db.createUser("studentteacher",null,"Giảng viên sinh viên","TEACHER","Teacher12345!".toCharArray()).identity().userId(),foreign=db.createUser("otherteacher",null,"Giảng viên khác","TEACHER","Teacher23456!".toCharArray()).identity().userId();String saved="";
  try(var core=new Server(0,temp.resolve("core.db"));var assignments=new AssignmentTcpServer(core.gateway(),temp.resolve("learning.db"),0,8,1,"unused");var web=new WebGatewayServer(core,assignments)){
   core.start();assignments.start();web.start();String base="http://127.0.0.1:"+web.port(),token=login(base,"studentteacher","Teacher12345!"),other=login(base,"otherteacher","Teacher23456!");String a=text(call(base,token,mapOf("action","CREATE_CLASS","roomCode","JAVA-K23")),"classId",""),b=text(call(base,token,mapOf("action","CREATE_CLASS","roomCode","OOP-K23")),"classId",""),outside=text(call(base,other,mapOf("action","CREATE_CLASS","roomCode","FOREIGN")),"classId","");
   String first=create(base,token,student("000123","Nguyễn Văn An","an.nguyen",a));saved=first;var u=user(base,token,first);check("000123".equals(u.get("studentCode")),"MSSV preserves leading zeros");check("an.nguyen@studyfix.local".equals(u.get("email")),"email persisted");check(number(u,"createdAt",0)>0,"creation time available");check(list(u.get("classes")).size()==1,"initial enrollment atomic with account creation");check(!stringify(u).contains("password"),"directory contains no password or hash");
   String studentToken=login(base,"an.nguyen","Student12345!");check(request(base,studentToken,"/api/admin",mapOf("action","STUDENT_CREATE")).status()==403,"student cannot create accounts");
   call(base,token,mapOf("action","STUDENT_UPDATE","userId",first,"studentCode","000123","username","an.updated","displayName","Nguyễn Văn An đã sửa","email","an.updated@studyfix.local","accountStatus","ACTIVE","classId","__KEEP__"));check(request(base,studentToken,"/api/me",null).status()==401,"editing revokes stale identities");check(request(base,"","/api/auth/login",mapOf("username","an.nguyen","password","Student12345!")).status()!=200,"old username no longer logs in");studentToken=login(base,"an.updated","Student12345!");
   check(request(base,token,"/api/admin",mapOf("action","STUDENT_UPDATE","userId",first,"studentCode","CHANGED","username","an.updated","displayName","An","accountStatus","ACTIVE")).status()==400,"MSSV immutable");check(request(base,other,"/api/admin",mapOf("action","STUDENT_DETAIL","userId",first)).status()==403,"foreign detail denied");
   call(base,token,mapOf("action","STUDENT_ASSIGN","userIds",List.of(first),"classId",b));check(list(user(base,token,first).get("classes")).size()==2,"add class preserves existing memberships");call(base,token,mapOf("action","STUDENT_ASSIGN","userIds",List.of(first),"classId",b,"fromClassId",a,"move",true));check(list(user(base,token,first).get("classes")).size()==1,"move removes only selected source class");check(!db.allowedInClass(a,first)&&db.allowedInClass(b,first),"membership updated on server");
   String second=create(base,token,student("SV002","Lê Thị Bích","bich.le",a));db.enrollment(foreign,outside,first,true);check(!Boolean.TRUE.equals(user(base,token,first).get("canManageAccount")),"shared student account protected");check(request(base,token,"/api/admin",mapOf("action","STUDENT_STATUS","userIds",List.of(second,first),"accountStatus","LOCKED")).status()==403,"bulk permission failure denied");check("ACTIVE".equals(user(base,token,second).get("accountStatus")),"bulk permission failure rolls back all rows");check(request(base,token,"/api/admin",mapOf("action","STUDENT_ASSIGN","userIds",List.of(second),"classId",outside)).status()==403,"foreign destination rejected");check(request(base,token,"/api/admin",mapOf("action","STUDENT_ASSIGN","userIds",List.of(second,first),"classId",b,"fromClassId",a,"move",true)).status()==400,"invalid source membership rejects whole transfer");check(db.allowedInClass(a,second),"failed transfer preserves source");check(db.allowedInClass(outside,first),"other teacher membership preserved");
   call(base,token,mapOf("action","STUDENT_STATUS","userIds",List.of(second),"accountStatus","LOCKED"));check("LOCKED".equals(user(base,token,second).get("accountStatus")),"locked state distinct");check(request(base,"","/api/auth/login",mapOf("username","bich.le","password","Student12345!")).status()!=200,"locked login blocked");call(base,token,mapOf("action","STUDENT_STATUS","userIds",List.of(second),"accountStatus","DISABLED"));check("DISABLED".equals(user(base,token,second).get("accountStatus")),"disabled state distinct and still visible");call(base,token,mapOf("action","STUDENT_STATUS","userIds",List.of(second),"accountStatus","ACTIVE"));login(base,"bich.le","Student12345!");
   int before=users(base,token).size();check(request(base,token,"/api/admin",mapOf("action","STUDENT_IMPORT","students",List.of(student("GOOD001","Valid row","good.new",a),student("SV002","Duplicate row","duplicate.new",a)))).status()==400,"duplicate MSSV import rejected");check(users(base,token).size()==before,"failed import creates no partial accounts");check(request(base,token,"/api/admin",mapOf("action","STUDENT_IMPORT","students",List.of(student("GOOD002","Valid row","good.second",a),student("BAD002","Foreign row","bad.foreign",outside)))).status()==403,"foreign import class rejected atomically");check(users(base,token).size()==before,"foreign class import rolls back all accounts");
   var imported=student("CSV001","Đặng Tuấn Kiệt","kiet.dang","");imported.remove("classId");imported.put("classCode","JAVA-K23");call(base,token,mapOf("action","STUDENT_IMPORT","students",List.of(imported)));
   List<List<String>> sheet=List.of(List.of("MSSV","Họ và tên","Tên đăng nhập","Mật khẩu","Email","Lớp"),List.of("XLSX001","Vũ Hoàng Mai","mai.vu","Student12345!","mai@studyfix.local","JAVA-K23"));byte[] xlsx=StudentSpreadsheet.write(sheet);check(xlsx[0]=='P'&&xlsx[1]=='K',"genuine XLSX ZIP container");check(StudentSpreadsheet.read(xlsx).equals(sheet),"Unicode OOXML inline string roundtrip");Files.write(Path.of("build-student-directory/import-sample.xlsx"),xlsx);check(preview(base,token,xlsx).statusCode()==200,"authorized Excel preview");check(preview(base,studentToken,xlsx).statusCode()==403,"student Excel preview forbidden");check(preview(base,token,"not excel".getBytes()).statusCode()==400,"invalid Excel rejected");check(preview(base,token,new byte[1048577]).statusCode()==413,"oversized Excel rejected");
   var csv=call(base,token,mapOf("action","STUDENT_EXPORT","format","CSV","classId",a));String text=new String(Base64.getDecoder().decode(text(csv,"base64","")),java.nio.charset.StandardCharsets.UTF_8);check(text.startsWith("\ufeff")&&text.contains("Đặng Tuấn Kiệt"),"CSV UTF-8 BOM and Unicode");check(!text.contains("Student12345!")&&!text.contains("password_hash"),"export excludes secrets");check(number(csv,"count",0)==2,"export class filter");var excel=call(base,token,mapOf("action","STUDENT_EXPORT","format","XLSX","classId",a));byte[] output=Base64.getDecoder().decode(text(excel,"base64",""));Files.write(Path.of("build-student-directory/export-sample.xlsx"),output);check(StudentSpreadsheet.read(output).size()==3,"Excel export includes exactly filtered rows and header");check(request(base,token,"/api/admin",mapOf("action","STUDENT_EXPORT","classId",outside)).status()==403,"foreign export class denied");check(number(call(base,token,mapOf("action","STUDENT_EXPORT","createdFrom","2099-01-01")),"count",-1)==0,"export honors advanced date filter");
   for(int i=3;i<=12;i++)create(base,token,student("SV"+String.format("%03d",i),"Sinh viên "+i,"student"+i,i%2==0?a:b));
   if(args.length>0&&args[0].equals("--browser")){Files.writeString(Path.of("build-student-directory/fixture.json"),stringify(mapOf("base",base,"directory",temp.toAbsolutePath().toString(),"classA",a,"classB",b)));System.out.println("BROWSER_READY "+base);System.out.flush();System.in.read();}
  }
  final String savedId=saved;var reopened=new ManagementDatabase(new ManagementConfig("jdbc:sqlite:"+management.toAbsolutePath()));check(list(reopened.dashboard(teacher,"").get("users")).stream().map(v->map(v)).anyMatch(u->savedId.equals(u.get("userId"))&&"an.updated@studyfix.local".equals(u.get("email"))),"email and status migration survives restart");System.out.println("StudentDirectoryIntegrationTest PASS: "+checks+" assertions.");
 }
}
